import { boundChildResultTelemetry } from "./result-telemetry.js";
/** Return child run snapshot usage. */
export function getChildRunSnapshotUsage(snapshot) {
    return snapshot?.usage;
}
function optionalUsage(usage) {
    return usage === undefined ? {} : { usage };
}
/** Builds child run execution snapshot. */
export function buildChildRunExecutionSnapshot(result) {
    return {
        success: result.success,
        description: result.description,
        fullResultText: result.success ? result.summary.text : null,
        error: result.success ? null : result.error,
        ...(!result.success && result.terminalErrorCode
            ? { terminalErrorCode: result.terminalErrorCode }
            : {}),
        steps: result.steps,
        toolCalls: result.toolCalls ?? [],
        toolResults: result.toolResults ?? [],
        ...(result.toolTelemetryOmitted ? { toolTelemetryOmitted: result.toolTelemetryOmitted } : {}),
        ...optionalUsage(result.usage),
        durationMs: result.durationMs ?? 0,
    };
}
/** Builds child run result common. */
export function buildChildRunResultCommon(input) {
    return input;
}
/** Result returned from build child run success. */
export function buildChildRunSuccessResult(common, summary) {
    return boundChildResultTelemetry({
        success: true,
        description: common.description,
        summary,
        steps: common.steps,
        toolCalls: common.toolCalls,
        toolResults: common.toolResults,
        ...(common.toolTelemetryOmitted ? { toolTelemetryOmitted: common.toolTelemetryOmitted } : {}),
        ...optionalUsage(common.usage),
        durationMs: common.durationMs,
    });
}
/** Result returned from build child run failure. */
export function buildChildRunFailureResult(common, error, terminalErrorCode) {
    return {
        success: false,
        description: common.description,
        error,
        ...(terminalErrorCode ? { terminalErrorCode } : {}),
        steps: common.steps,
        toolCalls: common.toolCalls,
        toolResults: common.toolResults,
        ...(common.toolTelemetryOmitted ? { toolTelemetryOmitted: common.toolTelemetryOmitted } : {}),
        ...optionalUsage(common.usage),
        durationMs: common.durationMs,
    };
}
/** Builds child run failure snapshot. */
export function buildChildRunFailureSnapshot(common, error, fullResultText, terminalErrorCode) {
    return {
        success: false,
        description: common.description,
        fullResultText,
        error,
        ...(terminalErrorCode ? { terminalErrorCode } : {}),
        steps: common.steps,
        toolCalls: common.toolCalls,
        toolResults: common.toolResults,
        ...(common.toolTelemetryOmitted ? { toolTelemetryOmitted: common.toolTelemetryOmitted } : {}),
        ...optionalUsage(common.usage),
        durationMs: common.durationMs,
    };
}
/** Builds child run success snapshot. */
export function buildChildRunSuccessSnapshot(common, fullResultText) {
    return {
        success: true,
        description: common.description,
        fullResultText,
        error: null,
        steps: common.steps,
        toolCalls: common.toolCalls,
        toolResults: common.toolResults,
        ...(common.toolTelemetryOmitted ? { toolTelemetryOmitted: common.toolTelemetryOmitted } : {}),
        ...optionalUsage(common.usage),
        durationMs: common.durationMs,
    };
}
